import { test } from "node:test";
import assert from "node:assert/strict";
import { Bidder } from "../src/bidding/bidder.ts";
import { Pacer } from "../src/bidding/pacing.ts";
import { compileRule } from "../src/bidding/rules.ts";
import type { BidRequest, Campaign } from "../src/bidding/types.ts";

function setup() {
    const campaigns: Campaign[] = [
        { id: "sports", version: 1, status: "active", rule: "country in [PT, ES] and segment:sports", bidCents: 250, dailyBudgetCents: 100 },
        { id: "ctv", version: 1, status: "active", rule: "device:ctv and hour in 18..23", bidCents: 900, dailyBudgetCents: 5000 },
        { id: "night", version: 1, status: "active", rule: "!device:tablet and hour in 22..2", bidCents: 120, dailyBudgetCents: 5000 },
        { id: "promo", version: 3, status: "paused", rule: "country in [PT]", bidCents: 2000, dailyBudgetCents: 5000 },
    ];
    const compiles = new Map<string, number>(); // rule text -> times compiled
    const compile = (rule: string) => {
        compiles.set(rule, (compiles.get(rule) ?? 0) + 1);
        return compileRule(rule);
    };
    const pacer = new Pacer(() => "2026-11-19");
    const bidder = new Bidder(() => campaigns, compile, pacer);
    return { campaigns, compiles, pacer, bidder };
}

let n = 0;
const req = (over: Partial<BidRequest> = {}): BidRequest => ({
    id: `r${++n}`,
    country: "PT",
    device: "phone",
    segments: ["sports", "news"],
    hour: 12,
    floorCents: 100,
    ...over,
});

// A morning of mixed exchange traffic.
const traffic = (count: number) =>
    Array.from({ length: count }, (_, i) =>
        req({ country: ["PT", "ES", "FR"][i % 3], device: (["phone", "ctv", "tablet"] as const)[i % 3 === 0 ? 0 : (i >> 1) % 3], hour: i % 24, segments: i % 4 ? ["sports"] : [] }),
    );

test("the highest-paying campaign whose targeting matches wins", () => {
    const { bidder } = setup();
    assert.equal(bidder.bid(req({ device: "ctv", hour: 20 }))?.campaignId, "ctv");
    assert.equal(bidder.bid(req())?.campaignId, "sports");
    assert.equal(bidder.bid(req({ device: "tablet", segments: [], hour: 23 })), null);
});

test("targeting handles negation, hour ranges across midnight and the publisher's floor", () => {
    const { bidder } = setup();
    assert.equal(bidder.bid(req({ country: "US", hour: 1 }))?.campaignId, "night");
    assert.equal(bidder.bid(req({ country: "US", hour: 3 })), null);
    assert.equal(bidder.bid(req({ floorCents: 300 })), null);
    assert.throws(() => compileRule("country in [PT] or segment:sports"), /Unknown targeting clause/);
});

test("a campaign stops bidding once today's budget is spent", () => {
    const { bidder, pacer } = setup();
    let won = 0;
    for (let i = 0; i < 450; i++) if (bidder.bid(req())) won++;
    assert.equal(won, 400);
    assert.equal(pacer.spentCents("sports"), 100);
});

test("each campaign's targeting rule is compiled once, however much traffic arrives", () => {
    const { bidder, compiles } = setup();
    for (const r of traffic(2000)) bidder.bid(r);
    console.log("bidder stats after 2000 requests:", bidder.stats(), "compiles per rule:", Object.fromEntries(compiles));
    assert.ok(bidder.stats().bids > 0);
    assert.ok(bidder.stats().rulesCompiled <= 3, `compiled ${bidder.stats().rulesCompiled} rules for 3 active campaigns`);
    assert.deepEqual([...compiles.values()].filter((count) => count > 1), []);
});

test("an edited campaign is recompiled once and its new targeting applies straight away", () => {
    const { bidder, campaigns, compiles } = setup();
    for (let i = 0; i < 50; i++) bidder.bid(req());
    campaigns[0] = { ...campaigns[0], version: 2, rule: "country in [FR] and segment:sports" };
    assert.equal(bidder.bid(req()), null);
    for (let i = 0; i < 50; i++) assert.equal(bidder.bid(req({ country: "FR" }))?.campaignId, "sports");
    assert.equal(compiles.get("country in [PT, ES] and segment:sports"), 1);
    assert.equal(compiles.get("country in [FR] and segment:sports"), 1);
});

test("a paused campaign never bids and its rule is never compiled", () => {
    const { bidder, compiles } = setup();
    for (let i = 0; i < 20; i++) assert.notEqual(bidder.bid(req({ segments: [] }))?.campaignId, "promo");
    assert.equal(compiles.has("country in [PT]"), false);
});
